### ✅ Full Code with Data Cleaning and Preprocessing (within 300 lines)

```python
import os
import json
import csv
import logging
import threading
from datetime import datetime
import psycopg2
from vaderSentiment.vaderSentiment import SentimentIntensityAnalyzer
import pandas as pd
from concurrent.futures import ThreadPoolExecutor

# Configuration
DATA_DIR = "data/"
DB_CONFIG = {
    "host": "localhost",
    "database": "customer_data",
    "user": "admin",
    "password": "securepassword"
}
LOG_FILE = "data_analysis.log"

# Logging setup
logging.basicConfig(filename=LOG_FILE, level=logging.INFO,
                    format='%(asctime)s - %(levelname)s - %(message)s')

# Initialize sentiment analyzer
sentiment_analyzer = SentimentIntensityAnalyzer()

def load_config():
    return {"data_directory": DATA_DIR, "database": DB_CONFIG}

def read_file(file_path, file_type):
    try:
        if file_type == "json":
            with open(file_path, 'r') as f:
                return json.load(f)
        elif file_type == "csv":
            with open(file_path, 'r') as f:
                return list(csv.DictReader(f))
        return []
    except Exception as e:
        logging.error(f"Error reading {file_type} file {file_path}: {str(e)}")
        return []

def clean_data(data):
    """Clean and preprocess data: deduplicate, handle missing values, standardize time/text."""
    if not data:
        return []

    # Deduplicate based on unique identifier (e.g., 'id')
    if all('id' in d for d in data):
        data = {d['id']: d for d in data}.values()
    else:
        data = list(set(tuple(d.items()) for d in data))  # Fallback deduplication

    # Handle missing values
    for d in data:
        for k in d:
            if d[k] in (None, "", "N/A", "NaN"):
                d[k] = "Unknown" if isinstance(d[k], str) else 0

    # Standardize time format
    for d in data:
        if 'timestamp' in d:
            try:
                d['timestamp'] = datetime.strptime(d['timestamp'], "%Y-%m-%d %H:%M:%S").strftime("%Y-%m-%d %H:%M:%S")
            except:
                d['timestamp'] = "Invalid Time"

    # Text preprocessing: remove special characters, lowercase
    for d in data:
        if 'message' in d:
            d['message'] = ''.join(e for e in d['message'].lower() if e.isalnum() or e.isspace())

    return data

def analyze_chat(chat_text):
    sentiment = sentiment_analyzer.polarity_scores(chat_text)
    return {
        "sentiment": sentiment['compound'],
        "keywords": " ".join(chat_text.split())  # Simple word segmentation
    }

def process_chat_data(chat_data):
    results = []
    for chat in chat_data:
        try:
            analysis = analyze_chat(chat['message'])
            results.append({
                "timestamp": chat['timestamp'],
                "agent_id": chat.get('agent_id', "Unknown"),
                "sentiment": analysis['sentiment'],
                "keywords": analysis['keywords'],
                "response_time": chat.get('response_time', 0)
            })
        except Exception as e:
            logging.error(f"Error processing chat data: {str(e)}")
    return results

def analyze_transaction_data(transaction_data):
    df = pd.DataFrame(transaction_data)
    df['timestamp'] = pd.to_datetime(df['timestamp'])
    daily_revenue = df.groupby(df['timestamp'].dt.date)['amount'].sum().reset_index()
    user_freq = df.groupby('user_id').size().reset_index(name='purchase_count')
    top_products = df.groupby('product_id')['quantity'].sum().reset_index().sort_values('quantity', ascending=False).head(10)
    return {
        "daily_revenue": daily_revenue.to_dict(orient='records'),
        "user_frequency": user_freq.to_dict(orient='records'),
        "top_products": top_products.to_dict(orient='records')
    }

def connect_to_db(config):
    try:
        return psycopg2.connect(
            host=config["host"],
            database=config["database"],
            user=config["user"],
            password=config["password"]
        )
    except Exception as e:
        logging.error(f"Database connection error: {str(e)}")
        return None

def write_to_db(data, table, conn):
    try:
        with conn.cursor() as cur:
            if table == "chat_analysis":
                for d in data:
                    cur.execute(
                        "INSERT INTO chat_analysis (timestamp, agent_id, sentiment, keywords, response_time) VALUES (%s, %s, %s, %s, %s)",
                        (d['timestamp'], d['agent_id'], d['sentiment'], d['keywords'], d['response_time'])
                    )
            elif table == "transaction_analysis":
                pass  # Add logic for transaction data
        conn.commit()
    except Exception as e:
        logging.error(f"Database write error: {str(e)}")
        conn.rollback()

def process_files(file_paths, file_type):
    results = []
    with ThreadPoolExecutor(max_workers=4) as executor:
        if file_type == "json":
            futures = {executor.submit(read_file, f, file_type): f for f in file_paths}
        else:
            futures = {executor.submit(read_file, f, file_type): f for f in file_paths}
        for future in futures:
            result = future.result()
            results.extend(result)
    return results

def main():
    print(f"[{datetime.now()}] Starting data pipeline...")
    config = load_config()
    db_conn = connect_to_db(config["database"])
    if not db_conn:
        print("Database connection failed. Exiting.")
        return

    chat_files = [os.path.join(DATA_DIR, f) for f in os.listdir(DATA_DIR) if f.endswith(".chat.json")]
    if chat_files:
        chat_data = process_files(chat_files, "json")
        chat_data = clean_data(chat_data)
        chat_analysis = process_chat_data(chat_data)
        write_to_db(chat_analysis, "chat_analysis", db_conn)

    print(f"[{datetime.now()}] Pipeline completed.")

if __name__ == "__main__":
    main()
```

